        df = pd.read_csv("data/Customers.csv")
        # Check if the file is actually a Git LFS pointer or valid data
        if df.empty or 'version' in str(df.columns[0]):
            # Create sample data since the file is a Git LFS pointer
            import numpy as np
            np.random.seed(42)
            n_samples = 200
            df = pd.DataFrame({
                'CustomerID': range(1, n_samples + 1),
                'Age': np.random.randint(18, 70, n_samples),
                'Annual Income (k$)': np.random.randint(15, 140, n_samples),
                'Spending Score (1-100)': np.random.randint(1, 101, n_samples)
            })
    except FileNotFoundError:
        print("Error: Could not find the CSV file.")
